22	/* The rows of a disc of each diameter up to DISC_MAX_W, relative to its corner.
23	 * canvas_fill_ellipse works each row out in double precision, which the S3 does
24	 * in software, and a round-capped line draws two discs per segment. A disc's
25	 * rows do not depend on where it sits, so they are worked out once per width.
26	 * A row with xb < xa is empty. */
27	#define DISC_MAX_W 16
28	typedef struct {
29	  int16_t xa, xb;
30	} disc_row;
31	static disc_row g_disc_rows[DISC_MAX_W + 1][DISC_MAX_W];
32	static bool g_disc_built[DISC_MAX_W + 1];
33	
34	/* The same arithmetic as canvas_fill_ellipse, for an ellipse at the origin. */
35	static void build_disc(int w) {
36	  const double centre = (w - 1) / 2.0, radius = w / 2.0;
37	  for (int row = 0; row < w; row++) {
38	    const double ny = (row - centre) / radius;
39	    const double t = 1.0 - ny * ny;
40	    disc_row d = {0, -1};
41	    if (t >= 0) {
42	      const double half = radius * sqrt(t);
43	      const int xa = (int)ceil(centre - half), xb = (int)floor(centre + half);
44	      if (xb >= xa) d = (disc_row){(int16_t)xa, (int16_t)xb};
45	    }
46	    g_disc_rows[w][row] = d;
47	  }
48	  g_disc_built[w] = true;
49	}
