92	static uint16_t swap16(uint16_t v) { return (uint16_t)((v << 8) | (v >> 8)); }
93	
94	/* Red and blue in bits 0-4 and 11-15, green in bits 21-26, so one multiply
95	 * scales all three channels and the gaps take the carries. */
96	#define SPREAD_MASK 0x07E0F81Fu
97	static uint32_t spread(uint16_t v) { return ((uint32_t)v | ((uint32_t)v << 16)) & SPREAD_MASK; }
98	static uint16_t unspread(uint32_t v) { return (uint16_t)((v & 0xFFFFu) | (v >> 16)); }
