157	/* Fills x0..x1 by y0..y1 (inclusive), clipped to the canvas first so the
158	 * ints handed on are small. */
159	static void fill_box(Canvas *c, wide_t x0, wide_t y0, wide_t x1, wide_t y1,
160	                     uint16_t colour) {
161	  x0 = max_w(x0, 0);
162	  y0 = max_w(y0, 0);
163	  x1 = min_w(x1, (wide_t)c->w - 1);
164	  y1 = min_w(y1, (wide_t)c->h - 1);
165	  if (x0 > x1 || y0 > y1) return;
166	  if (g_mask) {
167	    for (wide_t y = y0; y <= y1; y++) mask_row((int)y, (int)x0, (int)x1);
168	    return;
169	  }
170	  if (g_alpha) {
171	    blend_box(c, (int)x0, (int)y0, (int)(x1 - x0 + 1), (int)(y1 - y0 + 1), colour);
172	    return;
173	  }
174	  canvas_fill_rect(c, (int)x0, (int)y0, (int)(x1 - x0 + 1), (int)(y1 - y0 + 1),
175	                   colour);
176	}
