196	/* Clips the segment to the canvas grown by margin, in double, because the
197	 * ends can be anywhere in the int range. Returns 0 when nothing is left. */
198	static int clip_to_canvas(const Canvas *c, wide_t margin, double *x1,
199	                          double *y1, double *x2, double *y2) {
200	  const double xmin = -(double)margin, xmax = (double)c->w + margin;
201	  const double ymin = -(double)margin, ymax = (double)c->h + margin;
202	  const double dx = *x2 - *x1, dy = *y2 - *y1;
203	  const double p[4] = {-dx, dx, -dy, dy};
204	  const double q[4] = {*x1 - xmin, xmax - *x1, *y1 - ymin, ymax - *y1};
205	  double t0 = 0, t1 = 1;
206	  for (int i = 0; i < 4; i++) {
207	    if (p[i] == 0) {
208	      if (q[i] < 0) return 0;
209	    } else {
210	      const double t = q[i] / p[i];
211	      if (p[i] < 0) {
212	        if (t > t1) return 0;
213	        if (t > t0) t0 = t;
214	      } else {
215	        if (t < t0) return 0;
216	        if (t < t1) t1 = t;
217	      }
218	    }
219	  }
220	  const double ax = *x1 + t0 * dx, ay = *y1 + t0 * dy;
221	  const double bx = *x1 + t1 * dx, by = *y1 + t1 * dy;
222	  *x1 = ax;
223	  *y1 = ay;
224	  *x2 = bx;
225	  *y2 = by;
226	  return 1;
227	}
