350	/* Only a round cap overlaps the segment's own body. */
351	void stroke_segment_ends(Canvas *c, const struct XshimGC *gc, int x1, int y1,
352	                         int x2, int y2, int cap_start, int cap_end) {
353	  g_alpha = gc->alpha;
354	  const int overlaps = cap_start == CapRound || cap_end == CapRound;
355	  if (g_alpha && overlaps) open_mask(c);
356	  segment_pieces(c, gc, x1, y1, x2, y2, cap_start, cap_end);
357	  close_mask(c, (uint16_t)gc->foreground);
358	}
