360	void stroke_segment(Canvas *c, const struct XshimGC *gc, int x1, int y1, int x2,
361	                    int y2) {
362	  stroke_segment_ends(c, gc, x1, y1, x2, y2, gc->cap_style, gc->cap_style);
363	}
