365	/* The corner between a segment arriving along d1 and one leaving along d2
366	 * (unit vectors), at vertex (ix, iy). */
367	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
368	                    int style, uint16_t colour) {
369	  const float dot = d1.x * d2.x + d1.y * d2.y;
370	  const float cross = d1.x * d2.y - d1.y * d2.x;
371	  if (fabsf(cross) < 1e-4f && dot > 0) return;
372	  if (style == JoinRound) {
373	    disc(c, ix, iy, w, colour);
374	    return;
375	  }
376	  const vec2 v = vertex(ix, iy, w);
377	  const float half = (float)w / 2.0f;
378	  const float side = cross > 0 ? -1.0f : 1.0f;
379	  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
380	  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
381	  const vec2 p2 = {v.x + n2.x * half, v.y + n2.y * half};
382	  /* Xlib's miter limit of 10: the miter is longer than ten widths when the
383	   * segments meet at less than about 11.5 degrees, i.e. dot < -0.98. */
384	  if (style == JoinMiter && dot >= -0.98f) {
385	    const float k = half / (1.0f + dot);
386	    const float quad[4][2] = {{v.x, v.y},
387	                              {p1.x, p1.y},
388	                              {v.x + (n1.x + n2.x) * k, v.y + (n1.y + n2.y) * k},
389	                              {p2.x, p2.y}};
390	    fill_convex(c, quad, 4, colour);
391	    return;
392	  }
393	  const float tri[3][2] = {{v.x, v.y}, {p1.x, p1.y}, {p2.x, p2.y}};
394	  fill_convex(c, tri, 3, colour);
395	}
