      e->row = y;
      xs[nx++] = e->col + (e->rem != 0);
    }
    if (nx > SORT_INSERTION_MAX) {
      qsort(xs, (size_t)nx, sizeof(int), compare_ints);
    } else {
      for (int a = 1; a < nx; a++)
        for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
          const int tmp = xs[b];
          xs[b] = xs[b - 1];
          xs[b - 1] = tmp;
